import os, json

def _safe_load_json(p):
    try:
        with open(p, 'r') as f:
            return json.load(f)
    except Exception:
        return None

def read_pairs_csv(path):
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line[0].isalpha():
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0]); j = int(parts[1])
                    except Exception:
                        continue
                    if i > j: i, j = j, i
                    s.add((i, j))
    except Exception:
        return None
    return s

def read_boundary_csv(path):
    alias = {'xL':'xmin','xR':'xmax','yB':'ymin','yT':'ymax',
             'xmin':'xmin','xmax':'xmax','ymin':'ymin','ymax':'ymax'}
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0])
                    except Exception:
                        continue
                    kind = alias.get(parts[1], parts[1])
                    s.add((i, kind))
    except Exception:
        return None
    return s

def jacc(a, b):
    if a is None or b is None: return None, None, None
    inter = len(a & b); uni = len(a | b)
    j = (inter/uni) if uni else 1.0
    return j, inter, uni

def construct_packing():
    rows = []
    results = {}
    for n in range(25, 31):
        a_dir = f'storage/Aletheia/nmap/n{n}'
        s_dir = f'storage/Scientia/nmap/n{n}'
        a_sum = os.path.join(a_dir, 'summary_tol1e8.json')
        s_sum = os.path.join(s_dir, 'summary_tol1e8.json')
        a_bp  = os.path.join(a_dir, 'active_boundary_tol1e8.csv')
        a_pp  = os.path.join(a_dir, 'active_pairs_tol1e8.csv')
        s_bp  = os.path.join(s_dir, 'active_boundary_tol1e8.csv')
        s_pp  = os.path.join(s_dir, 'active_pairs_tol1e8.csv')

        A = _safe_load_json(a_sum)
        S = _safe_load_json(s_sum)
        if not A or not S:
            continue
        sigA = A.get('sigma_r', None)
        sigS = S.get('sigma_r', None)
        if sigA is None or sigS is None:
            continue

        Ab = read_boundary_csv(a_bp); Ap = read_pairs_csv(a_pp)
        Sb = read_boundary_csv(s_bp); Sp = read_pairs_csv(s_pp)
        jb, ibi, ubu = jacc(Ab, Sb)
        jp, ipi, upu = jacc(Ap, Sp)

        rec = {
            'n': n,
            'sigma_A': sigA,
            'sigma_S': sigS,
            'delta_sigma': sigS - sigA,
            'boundary_j': jb, 'boundary_inter': ibi, 'boundary_union': ubu,
            'pairs_j': jp, 'pairs_inter': ipi, 'pairs_union': upu
        }
        rows.append(rec)
        results[str(n)] = rec

    # write outputs
    try:
        os.makedirs('storage/noesis/nmap', exist_ok=True)
        with open('storage/noesis/nmap/delta_vs_similarity.json', 'w') as f:
            json.dump({'tol': 1e-8, 'rows': rows, 'by_n': results}, f, indent=2)
    except Exception:
        pass

    try:
        with open('storage/noesis/nmap/delta_vs_similarity.csv', 'w') as f:
            f.write('n,sigma_A,sigma_S,delta_sigma,boundary_j,pairs_j,boundary_inter,boundary_union,pairs_inter,pairs_union\n')
            for r in sorted(rows, key=lambda x: x['n']):
                f.write(f"{r['n']},{r['sigma_A']},{r['sigma_S']},{r['delta_sigma']},{'' if r['boundary_j'] is None else r['boundary_j']},{'' if r['pairs_j'] is None else r['pairs_j']},{'' if r['boundary_inter'] is None else r['boundary_inter']},{'' if r['boundary_union'] is None else r['boundary_union']},{'' if r['pairs_inter'] is None else r['pairs_inter']},{'' if r['pairs_union'] is None else r['pairs_union']}\n")
    except Exception:
        pass

    # return baseline
    try:
        import numpy as np
        c = np.loadtxt('storage/noesis/latest_centers.txt', dtype=float).reshape(26,2)
        r = np.loadtxt('storage/noesis/latest_radii.txt', dtype=float).reshape(26,)
    except Exception:
        import numpy as np
        coords = [0.1,0.3,0.5,0.7,0.9]
        centers = np.array([[x,y] for x in coords for y in coords], float)
        hole = np.array([0.2,0.2], float)
        centers = np.vstack([centers, hole])
        r0 = 0.1 - 1e-8
        d = float(np.linalg.norm(hole - np.array([0.1,0.1])))
        radii = np.array([r0]*25 + [d - r0 - 1e-8], float)
        c, r = centers, radii
    return c.astype(float), r.astype(float)
